import{_ as e,o as S,b as t,q as l}from"./chunks/framework.Tf23FRXt.js";const r=JSON.parse('{"title":"电脑梦境斯提格玛四","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[{"level":3,"title":"BOSS 1 欧米茄原型","slug":"boss-1-欧米茄原型","link":"#boss-1-欧米茄原型","children":[]}]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 拉姆达总领","slug":"boss-2-拉姆达总领","link":"#boss-2-拉姆达总领","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 斯提格玛四","slug":"boss-3-斯提格玛四","link":"#boss-3-斯提格玛四","children":[]}]}],"relativePath":"duty/784.htm.md","filePath":"duty/784.md","lastUpdated":1791101830000}'),i={name:"duty/784.htm.md"};function o(p,s,a,d,n,O){return S(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="电脑梦境斯提格玛四" tabindex="-1">电脑梦境斯提格玛四</h1><p>有点黑客帝国的感觉。</p><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>没什么特别的。</p><h3 id="boss-1-欧米茄原型" tabindex="-1">BOSS 1 欧米茄原型</h3><p>出啥躲啥。</p><p>读条<mark>前 / 后方迎击火箭</mark>时，会以 BOSS 前 / 后半场出 AOE，去另一侧躲避。</p><p>点名分散圈时会在地面上留下火圈，尽量把火圈放在场地边缘。</p><p>BOSS 读条<mark>欧米茄滑跃</mark>时，会随机点名一名玩家，同时出现分摊和击退标记，所有人尽量在中场靠近分摊，击退时小心不要被击退进火圈。</p><p>被连线火箭弹的玩家就躲开跑就行，注意尽量不要让连线横穿其他玩家。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>没什么特别的。</p><h3 id="boss-2-拉姆达总领" tabindex="-1">BOSS 2 拉姆达总领</h3><p>场地出现红色预警轨迹后，BOSS 会沿着轨迹在场地横冲直撞，最后到场边向场中发射半场 AOE。注意观察轨迹终点，在安全范围内向终点方向靠近。</p><p>读条<mark>狙击式波动炮</mark>时，场地中央出现 AOE 范围预警，并同时出现圆点标记（俗称麻将），有相同数量圆点的玩家在圆点附近等待引导 AOE。BOSS 读条结束后会激活场地中央的圆点，令 1 点发射直线 AOE 到头顶 1 点的玩家，2 点发射直线 AOE 到头顶 2 点的玩家，以此类推。</p><h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>没什么特别的。</p><h3 id="boss-3-斯提格玛四" tabindex="-1">BOSS 3 斯提格玛四</h3><p>BOSS 先在南场召唤小怪，放半场 AOE 后自爆，请在小怪自爆前击杀。</p><p>之后在西场召唤小怪，放正面扇形 AOE 后自爆，请靠近西场躲避 AOE，在小怪自爆前击杀。</p><p>BOSS 变身为螺旋柱体的时候，需要远离 BOSS；变身为圆环形时，需要靠近 BOSS。之后这个机制会与强制移动机制组合，注意自己的移动方向处理（移动距离大约是 1 个 BOSS 圈直径差一点）。</p>',21)])])}const B=e(i,[["render",o]]);export{r as __pageData,B as default};
